      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "intro_text",
        "detailed_analysis_h2",
        "units_sold_chart_h3",
        "units_sold_chart_desc",
        "units_sold_chart",
        "revenue_breakdown_h3",
        "revenue_breakdown_desc",
        "revenue_table"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Sales Performance Overview",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "This analysis provides a breakdown of units sold by product and calculates the total revenue generated by each product from the provided dataset.",
        "variant": "body"
      },
      "children": []
    },
    "detailed_analysis_h2": {
      "type": "Text",
      "props": {
        "text": "Detailed Product Analysis",
        "variant": "h2"
      },
      "children": []
