      "type": "Text",
      "props": {
        "text": "Units Sold Distribution (Table Data)",
        "variant": "h3"
      },
      "children": []
    },
    "units_sold_chart_desc": {
      "type": "Text",
      "props": {
        "text": "This table provides the data for the distribution of units sold for each product.",
        "variant": "body"
      },
      "children": []
    },
    "units_sold_chart": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "Product", "label": "Product" },
