          {
            "Product": "C",
            "Units Sold": 120,
            "Percentage of Total Units Sold": "25.53%"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table",
        "numericColumns": ["Units Sold", "Percentage of Total Units Sold"]
      },
      "children": []
    },
    "revenue_breakdown_h3": {
      "type": "Text",
      "props": {
        "text": "Product Revenue Breakdown",
        "variant": "h3"
      },
      "children": []
    },
    "revenue_breakdown_desc": {
      "type": "Text",
      "props": {
        "text": "This table presents the calculated total revenue for each product.",
        "variant": "body"
      },
      "children": []
    },
    "revenue_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Product",
